/// <summary>
/// The form event handler class for ReqItemTable form.
/// </summary>
public class METReqItemTableFormEventHandler
{        
    
}

Method.Source:
    /// <summary>
    /// ReqItemTable_OnWritten
    /// </summary>
    /// <param name="sender">Form Data Source</param>
    /// <param name="e">Form data source event</param>
    [FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, ReqItemTable), FormDataSourceEventType::Written),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void ReqItemTable_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun         fr                  = sender.formRun();
        ReqItemTable    metReqItemTable        = sender.cursor();        

        if (metReqItemTable)
        {   
            METReqItemTable metReqItemTableExt     = fr.dataHelper().FindDataSource(formDataSourceStr(ReqItemTable, METReqItemTable)).cursor();

            metReqItemTable.metPackMETReqItemTable(metReqItemTableExt);
            metReqItemTableExt.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metReqItemTable);
        }
    }

/// <summary>
/// Event handler when <c>ReqItemTable</c> form is initialized.
/// </summary>
/// <param name = "sender">Form object.</param>
/// <param name = "e">Form event args.</param>
[FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, ReqItemTable), FormDataSourceEventType::Initialized)]
public static void ReqItemTable_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
    /// CB269 - Item MDR
    /// If Item coverage > Planned order type is set to ‘Transfer’, then ‘Alternate sell unit warehouse’ field will be editable
    /// If Item coverage > Planned order type is set to ‘Purchase order’, then ‘Alternate sell unit warehouse’ field value will be cleared, and the field will be disabled.

    METReqItemTableFormEventHandler::enableAlternateSellUnitField(sender.formRun());
    
}

