/// <summary>
/// Event handler when <c>ReqItemTable.ReqPOType</c> field is modified.
/// </summary>
/// <param name = "sender">Form object.</param>
/// <param name = "e">Form event args.</param>
[FormDataFieldEventHandler(formDataFieldStr(ReqItemTable, ReqItemTable, ReqPOType), FormDataFieldEventType::Modified)]
public static void ReqPOType_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    /// CB269 - Item MDR
    /// If Item coverage > Planned order type is set to ‘Transfer’, then ‘Alternate sell unit warehouse’ field will be editable
    /// If Item coverage > Planned order type is set to ‘Purchase order’, then ‘Alternate sell unit warehouse’ field value will be cleared, and the field will be disabled.

    METReqItemTableFormEventHandler::enableAlternateSellUnitField(sender.datasource().formRun());
}

    /// <summary>
    /// CB269 - Item MDR
    /// If Item coverage > Planned order type is set to ‘Transfer’, then ‘Alternate sell unit warehouse’ field will be editable
    /// If Item coverage > Planned order type is set to ‘Purchase order’, then ‘Alternate sell unit warehouse’ field value will be cleared, and the field will be disabled.
    /// </summary>
    /// <param name = "element">FormRun object.</param>
    public static void enableAlternateSellUnitField(FormRun element)
    {
        
        ReqItemTable                reqItemTable        = element.dataSource(formDataSourceStr(ReqItemTable, ReqItemTable)).cursor() as reqItemTable ;
        METReqItemTable             metReqItemTable     = element.dataSource(formDataSourceStr(ReqItemTable, METReqItemTable)).cursor() as METReqItemTable;
       
        FormstringControl alternateSellUnitWH = element.design().controlName(formControlStr(ReqItemTable, METReqItemTable_AlternateSellUnitWH)) as FormstringControl;

        switch(reqItemTable.ReqPOType)
        {
            case ReqPOType::Transfer:
                /// If Item coverage > Planned order type is set to ‘Transfer’, then ‘Alternate sell unit warehouse’ field will be editable
                /// Additional logic to check Main warehouse specified
                alternateSellUnitWH.allowEdit(true);                
                break;
            
            case ReqPOType::Purch:
                /// If Item coverage > Planned order type is set to ‘Purchase order’, then ‘Alternate sell unit warehouse’ field value will be cleared, and the field will be disabled.
                alternateSellUnitWH.allowEdit(false);
                metReqItemTable.alternateSellUnitWH = '';
                break;

            default:
                break;
        } 

      
    }

    /// <summary>
    /// Event Handler to validate write into ReqItemTable
    /// </summary>
    /// <param name="sender">Form object.</param>
    /// <param name="e">Form event args.</param>
    [FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, ReqItemTable), FormDataSourceEventType::ValidatedWrite)]
    public static void ReqItemTable_OnValidatedWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        var                     args                = e as FormDataSourceCancelEventArgs;
        FormRun                 formRun             = sender.formRun();
        METReqItemTable         metReqItemTable     = formRun.dataSource(formDataSourceStr(ReqItemTable,METReqItemTable)).cursor() as METReqItemTable;
        ReqItemTable            reqItemTable        = formRun.dataSource(formDataSourceStr(ReqItemTable,ReqItemTable)).cursor() as ReqItemTable;

        /// cb269 item mdr
        /// alternate sell unit warehouse field must not be blank for "transfer" planned order type.
        if (reqItemTable.reqpotype == reqpotype::transfer && metReqItemTable.alternatesellunitwh == '')
        {
            Valid ret = checkfailed("@MET:AlternateSellUnitMandatory");
            args.cancel(ret);
        }
    }

    /// <summary>
    /// VM - CB264 - Pickupslot
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [FormControlEventHandler(formControlStr(ReqItemTable, METReqItemTable_OSCCode), FormControlEventType::Lookup)]
    public static void METReqItemTable_OSCCode_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        SysTableLookup      sysTableLookup  = SysTableLookup::newParameters(tableNum(METOrderSplitCategoryArea), sender);
        
        // Add the lookup columns
        sysTableLookup.addLookupfield(fieldNum(METOrderSplitCategoryArea, CategoryArea));
        sysTableLookup.addLookupfield(fieldNum(METOrderSplitCategoryArea, OSCC));
        sysTableLookup.addLookupfield(fieldNum(METOrderSplitCategoryArea, Area));

        // Run the lookup
        sysTableLookup.performFormLookup();

        //cancel the call to super() to prevent the system from trying to show
        FormControlCancelableSuperEventArgs cancelableSuperEventArgs = e as FormControlCancelableSuperEventArgs;
        cancelableSuperEventArgs.CancelSuperCall();
    }
